// ─── Transform Medusa Order → ERPNext Sales Invoice ─────────────
const orderData = $input.first().json;
const order = orderData.order || orderData;

// Extract customer
const customerEmail = order.email || 'walk-in@customer.local';
const customerName = order.shipping_address?.first_name
  ? `${order.shipping_address.first_name} ${order.shipping_address.last_name || ''}`
  : customerEmail;

// Extract line items → ERPNext Sales Invoice Items
const items = (order.items || []).map(item => {
  const sku = item.variant_sku || item.product_id?.replace('prod_', 'INVT-');
  return {
    item_code: sku,
    item_name: item.title,
    qty: item.quantity || 1,
    rate: (item.unit_price || 0) / 100, // Medusa uses cents
  };
});

// Calculate total
const total = (order.total || 0) / 100;

console.log(`[ERPNext Sync] Order ${order.id}: ${items.length} items, $${total}, customer: ${customerName}`);

return [{
  json: {
    order_id: order.id,
    customer_email: customerEmail,
    customer_name: customerName,
    currency: order.currency_code || 'USD',
    items: items,
    total: total,
    created_at: order.created_at,
  }
}];

// ─── Check if customer exists ─────────────────────────────────────
const response = $input.first().json;
const prevData = $('Transform Order Data').first().json;
const customers = response.data || [];

if (customers.length > 0) {
  console.log(`[ERPNext Sync] Customer found: ${customers[0].name}`);
  return [{ json: { ...prevData, erpnext_customer: customers[0].name, customer_exists: true } }];
} else {
  console.log(`[ERPNext Sync] Customer not found, will create: ${prevData.customer_name}`);
  return [{ json: { ...prevData, customer_exists: false } }];
}

// ─── Set customer name after creation ─────────────────────────────
const prevData = $('Customer Exists?').first().json;
const created = $input.first().json;
const customerName = created.data?.name || prevData.customer_name;
return [{ json: { ...prevData, erpnext_customer: customerName } }];

const result = $input.first().json;
console.log(`[ERPNext Sync] ✓ Sales Invoice created: ${result.data?.name || 'pending'}`);
return [$input.first()];
